"""Policy briefs (English + Urdu) per province and disease, generated by the Insight Agent.

Each brief = forecast table for the province (numbers from gold.forecast_*, with ids) + cited
guidance. Regenerated every hourly run so the dashboard never shows stale text.
"""
from __future__ import annotations

import json

import duckdb

from .. import config
from .agent import InsightAgent

QUESTION = {
    "en": "Which districts in {p} have the highest {d} risk next week, and what prevention and control should be done?",
    "ur": "اگلے ہفتے {p} کے کس ضلع میں {d} کا خطرہ زیادہ ہے اور بچاؤ اور کنٹرول کے لیے کیا کرنا چاہیے؟",
}
D_UR = {"malaria": "ملیریا", "dengue": "ڈینگی"}
ACTION_QUERY = {
    "malaria": "malaria prevention and control measures: insecticide-treated mosquito nets, indoor residual spraying, "
               "eliminate stagnant water and larval breeding sites, early diagnosis with RDT or microscopy and prompt treatment",
    "dengue": "dengue prevention and control measures: remove stagnant water and breeding sites, cover water containers, "
              "fogging and larviciding, mosquito repellent and nets, paracetamol not aspirin, warning signs go to hospital",
}


def generate() -> list[dict]:
    agent = InsightAgent()
    out = []
    for disease in config.TARGET_DISEASES:
        try:
            provs = agent.con.execute(f"SELECT DISTINCT province FROM gold.forecast_{disease}").df()["province"]
        except duckdb.CatalogException:
            continue
        for prov in provs:
            for lang in ("en", "ur"):
                q = QUESTION[lang].format(p=prov, d=disease if lang == "en" else D_UR[disease])
                # the Urdu question names the province in English, so parsing stays exact
                # briefs need actions a district can take, so retrieval asks for control measures explicitly
                a = agent.answer(q, lang=lang, guidance_only=True, guidance_query=ACTION_QUERY[disease])
                out.append({"brief_id": f"brief-{disease}-{prov}-{lang}", "disease": disease, "province": prov,
                            **a.to_dict()})
    (config.ARTIFACTS / "briefs.json").write_text(json.dumps(out, ensure_ascii=False, indent=2, default=str),
                                                  encoding="utf-8")
    return out
